// A realistic test alert, so the workflow can be run without waiting for a real one.
return [{ json: { body: { alerts: [{
  status: 'firing',
  labels: { alertname: 'DiskAlmostFull', instance: '127.0.0.1:9100', severity: 'critical' },
  annotations: { summary: 'Root disk above 95% on 127.0.0.1:9100', description: 'The root filesystem is almost full.' },
  startsAt: new Date().toISOString(),
  fingerprint: 'manual-test',
}]}}}];

// Turns the Alertmanager payload into one item per alert (firing or resolved).
// For each alert it picks the metric to look up and the runbook to use.
const RUNBOOKS = {
  "DiskAlmostFull": "# Runbook: Disk almost full\n1. Find the biggest folders: `sudo du -xh / --max-depth=2 | sort -rh | head -20`.\n2. Check logs and old journals: `/var/log`, `journalctl --disk-usage`, then `sudo journalctl --vacuum-size=500M`.\n3. Remove unused container images: `docker image prune` (only dangling images).\n4. Clear package and tool caches (apt, pip, browser test caches) if they are large.\n5. If nothing can be removed, plan more disk space and tell the service owner.",
  "HighCPU": "# Runbook: High CPU\n1. Find the processes using the most CPU: `top -o %CPU` or `ps aux --sort=-%cpu | head`.\n2. Check if a known batch job, backup or build is running and when it ends.\n3. If one process is stuck in a loop, restart that service, not the whole server.\n4. If load is real customer traffic, scale out or move workloads.",
  "HighMemory": "# Runbook: High memory\n1. Find the processes using the most memory: `ps aux --sort=-%mem | head`.\n2. Check for a memory leak: does one process grow steadily over hours?\n3. Restart the leaking service during a quiet time and open a bug for its owner.\n4. Check swap usage: heavy swapping makes the whole server slow.",
  "ServiceDown": "# Runbook: Service down\n1. Check if the process or container is running: `docker ps -a` or `systemctl status <service>`.\n2. Read the last log lines: `docker logs --tail 100 <container>` or `journalctl -u <service> -n 100`.\n3. Restart the service once. If it stops again, do not loop restarts: escalate to the owner.\n4. Check dependencies: database, disk space, network, expired certificates."
};
const QUERIES = {
  HighCPU: '100 - avg(rate(node_cpu_seconds_total{mode="idle"}[1m])) * 100',
  HighMemory: '(1 - node_memory_MemAvailable_bytes / node_memory_MemTotal_bytes) * 100',
  DiskAlmostFull: '(1 - node_filesystem_avail_bytes{mountpoint="/",fstype!~"tmpfs|overlay"} / node_filesystem_size_bytes{mountpoint="/",fstype!~"tmpfs|overlay"}) * 100',
  ServiceDown: 'up{job="shop"}',
};
const LABELS = {
  HighCPU: 'CPU usage in %',
  HighMemory: 'memory usage in %',
  DiskAlmostFull: 'root disk usage in %',
  ServiceDown: 'service status (1 = up, 0 = down)',
};
const first = $input.first().json;
const body = first.body ?? first;
const alerts = body.alerts || [];
return alerts.map(a => ({ json: {
  status: a.status,
  alertname: a.labels.alertname,
  instance: a.labels.instance || '',
  service: a.labels.job || '',
  severity: a.labels.severity || '',
  summary: (a.annotations && a.annotations.summary) || '',
  description: (a.annotations && a.annotations.description) || '',
  startsAt: a.startsAt,
  fingerprint: a.fingerprint || '',
  expr: QUERIES[a.labels.alertname] || 'vector(0)',
  metric_label: LABELS[a.labels.alertname] || 'metric value',
  runbook: RUNBOOKS[a.labels.alertname] || 'No runbook found for this alert.',
}}));

const a = $('Prepare').item.json;
const value = r => (r && r.data && r.data.result && r.data.result[0]) ? Number(r.data.result[0].value[1]) : null;
const round = v => v === null || Number.isNaN(v) ? null : Math.round(v * 10) / 10;
const now = round(value($('Metric now').item.json));
const ago = round(value($json));

// Describe the change over the last hour in one sentence.
let trend;
const state = v => (v === 1 ? 'up' : 'down');
if (now === null) trend = 'The current value could not be read.';
else if (a.alertname === 'ServiceDown') trend = ago === null
  ? `The service is ${state(now)} now. There is no value from 1 hour ago.`
  : `The service is ${state(now)} now and was ${state(ago)} one hour ago.`;
else if (ago === null) trend = `The value is ${now} now. There is no value from 1 hour ago, so it is unknown how long this has lasted.`;
else if (Math.abs(now - ago) < 2) trend = `The value has stayed about the same for the last hour (${ago} then, ${now} now).`;
else if (now > ago) trend = `The value rose from ${ago} one hour ago to ${now} now, so the problem started within the last hour.`;
else trend = `The value fell from ${ago} one hour ago to ${now} now.`;

return { json: { ...a, metric_now: now, metric_1h_ago: ago, trend } };

const a = $('Build context').item.json;
let r = {};
try { r = JSON.parse($json.response); } catch (e) { r = { likely_cause: 'The model did not return valid JSON.' }; }
const steps = Array.isArray(r.first_steps)
  ? r.first_steps.map((s, i) => `${i + 1}. ${typeof s === 'string' ? s : JSON.stringify(s)}`).join('\n')
  : String(r.first_steps || '');
// The model suggests a priority, but a fixed rule sets the limit:
// only critical alerts may be P1, warnings are at most P2.
const ORDER = ['P1', 'P2', 'P3'];
const highestAllowed = a.severity === 'critical' ? 'P1' : 'P2';
const suggested = ORDER.includes(r.priority) ? r.priority : highestAllowed;
const priority = ORDER.indexOf(suggested) < ORDER.indexOf(highestAllowed) ? highestAllowed : suggested;
return { json: {
  alertname: a.alertname,
  instance: a.instance,
  severity: a.severity,
  priority,
  summary: String(r.summary || a.summary),
  likely_cause: String(r.likely_cause || ''),
  first_steps: steps,
  runbook: a.runbook.split('\n')[0].replace('# Runbook: ', ''),
  metric_now: a.metric_now,
  metric_1h_ago: a.metric_1h_ago,
  fingerprint: a.fingerprint,
}};

const t = $json;
return { json: { ticket_id: t.id, report:
  `[${t.priority}] ${t.summary}\n` +
  `Server: ${t.instance}   Alert: ${t.alertname}\n` +
  `Metric now: ${t.metric_now}   1 hour ago: ${t.metric_1h_ago}\n` +
  `Likely cause: ${t.likely_cause}\n` +
  `First steps:\n${t.first_steps}\n` +
  `Runbook: ${t.runbook}   Ticket #${t.id}` } };

// Decides what to do with each alert:
//   new    = firing, no open ticket yet  -> LLM report and a new ticket
//   repeat = firing, ticket already open -> only count it, no new ticket
//   close  = resolved, ticket open       -> close the ticket
const out = [];
$input.all().forEach((item, i) => {
  const a = $('Prepare').itemMatching(i).json;
  const openId = item.json.open_id ?? null;
  let action = null;
  if (a.status === 'resolved') action = openId ? 'close' : null;
  else action = openId ? 'repeat' : 'new';
  if (action) out.push({ json: { ...a, open_id: openId, action }, pairedItem: { item: i } });
});
return out;
